reply:
I've built this as a single surface: a status filter above a sortable table of the eight items, with a short summary alongside. The catalog has no filter function, so the segmented control is wired to the `status_filter` name, but narrowing the rows has to be handled by the client.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "work_items",
      "catalogId": "https://a2uicatalog.ai/catalog/d-t4.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "work_items",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "1.5rem",
          "align": "stretch",
          "items": [
            {
              "blocks": [
                {
                  "id": "title",
                  "component": "heading",
                  "text": "Work items"
                },
                {
                  "id": "status_filter",
                  "component": "segmented_control",
                  "name": "status_filter",
                  "selected_value": "all",
                  "options": "[{\"label\":\"All\",\"value\":\"all\"},{\"label\":\"Done\",\"value\":\"done\"},{\"label\":\"In progress\",\"value\":\"in_progress\"},{\"label\":\"Blocked\",\"value\":\"blocked\"},{\"label\":\"Not started\",\"value\":\"not_started\"}]"
                },
                {
                  "id": "items_table",
                  "component": "data_table_sortable",
                  "headers": ["Item", "Status", "Detail"],
                  "rows": [
                    ["Auth service migration", "Done", "Token refresh moved to new gateway"],
                    ["Billing export job", "In progress", "Nightly CSV export being backfilled"],
                    ["Mobile onboarding flow", "In progress", "Step 3 copy under legal review"],
                    ["Search index rebuild", "Blocked", "Waiting on storage quota increase"],
                    ["Audit log retention", "Not started", "Policy draft awaiting sign-off"],
                    ["Dashboard latency fix", "Done", "P95 load time down to 1.2s"],
                    ["Payment webhook retries", "Blocked", "Vendor sandbox returning 503s"],
                    ["Docs site redesign", "In progress", "Navigation mockups in review"]
                  ]
                }
              ]
            },
            {
              "blocks": [
                {
                  "id": "summary",
                  "component": "body",
                  "text": "Showing 8 items. Use the status filter to narrow the list to one status."
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
